let active=null;const FRAME_COUNT=17,frameUrl=index=>`assets/avatar/turn/frame-${String(index).padStart(2,'0')}.jpg`;
function stop(){if(!active)return;active.stage.removeEventListener('pointermove',active.move);active.stage.removeEventListener('pointerleave',active.leave);active=null;}
function start(){stop();const stage=document.querySelector('[data-avatar-video-stage]'),idle=stage?.querySelector('.avatar-video-idle'),seed=stage?.querySelector('.avatar-video-turn-frame');if(!stage||!idle||!seed)return;const frames=Array.from({length:FRAME_COUNT},(_,index)=>{const image=index===8?seed:new Image();image.className='avatar-video avatar-video-turn-frame';image.alt='';image.setAttribute('aria-hidden','true');image.decoding='async';image.src=frameUrl(index);image.dataset.frame=String(index);if(image!==seed)stage.insertBefore(image,seed.nextSibling);return image}),select=index=>{frames.forEach((image,current)=>image.classList.toggle('is-current',current===index))},leave=()=>{stage.classList.remove('is-following');idle.play().catch(()=>{})},move=event=>{const rect=stage.getBoundingClientRect(),ratio=Math.min(1,Math.max(0,(event.clientX-rect.left)/rect.width)),index=Math.round(ratio*(FRAME_COUNT-1));select(index);stage.classList.add('is-following');idle.pause()};select(8);Promise.allSettled(frames.map(image=>image.decode?.())).then(()=>stage.dataset.framesReady='true');stage.addEventListener('pointermove',move,{passive:true});stage.addEventListener('pointerleave',leave);active={stage,idle,frames,move,leave};}
window.startAvatarVideoTheme=start;window.stopAvatarVideoTheme=stop;
